def max_Prime_Factors(num):
  largest_factor = -1
  while num % 2 == 0:
      largest_factor = 2
      num //= 2
  for i in range(3, int(math.sqrt(num)) + 1, 2):
      while num % i == 0:
          largest_factor = i
          num //= i
  if num > 2:
      largest_factor = num
  return largest_factor

