def rearange_string(s):
  count_dict = Counter(s)
  max_count = max(count_dict.values())
  if max_count > len(s)/2:
      return "Not possible"
  else:
      sorted_chars = sorted(count_dict.keys(), key=lambda x: count_dict[x])
      result = []
      i = 0
      while i < len(sorted_chars):
          result.append(sorted_chars[i])
          if i+1 < len(sorted_chars) and sorted_chars[i] != sorted_chars[i+1]:
              result.append(sorted_chars[i+1])
          i += 2
      return ''.join(result)

