def max_len_sub(arr,n):
  dp = [[0]*n for _ in range(n)]
  for i in range(n):
    dp[i][i] = 1
  for i in range(n-1,-1,-1):
    for j in range(i+1,n):
      if arr[j] - arr[i] <= 1:
        dp[i][j] = dp[i+1][j-1] + 2
      else:
        dp[i][j] = max(dp[i+1][j],dp[i][j-1])
  return max(max(row) for row in dp)

