def comb_sort(arr):
  gap = len(arr)
  swapped = True
  while gap > 1 or swapped:
    if gap > 1:
      gap = int(gap / 1.3)
    if gap < 1:
      gap = 1
    swapped = False
    i = 0
    while i + gap < len(arr):
      if arr[i] > arr[i + gap]:
        arr[i], arr[i + gap] = arr[i + gap], arr[i]
        swapped = True
      i += 1
  return arr

