def magic_square_test(square):
  # Calculate the sum of the first row
  sum_first_row = sum(square[0])

  # Check if all rows have the same sum
  for row in square:
    if sum(row) != sum_first_row:
      return False

  # Check if all columns have the same sum
  for col in range(len(square)):
    column_sum = sum(square[row][col] for row in range(len(square)))
    if column_sum != sum_first_row:
      return False

  # Check if the diagonals have the same sum
  diagonal_sum1 = sum(square[i][i] for i in range(len(square)))
  diagonal_sum2 = sum(square[i][len(square)-1-i] for i in range(len(square)))
  if diagonal_sum1 != sum_first_row or diagonal_sum2 != sum_first_row:
    return False

  return True

