  for i in range(n-1, -1, -1):
      for j in range(i+1, n):
          if s[i] == s[j]:
              dp[i][j] = 1 + dp[i+1][j-1]
              if dp[i][j] > max_length:
                  max_length = dp[i][j]
                  start_index = i
