    # If target is 0, then answer is true
    for i in range(n+1):
        dp[i][0] = True
    
    # Fill the table in bottom-up manner
    for i in range(1, n+1):
        for j in range(1, target+1):
            if arr[i-1] <= j:
                dp[i][j] = dp[i-1][j] or dp[i-1][j - arr[i-1]]
